import { nativeSdkApplicationForRun } from '../../../domains/comet-native/native-sdk-application.js';
import { createRuntime, createFileRuntimeStore } from '../../../domains/engine/runtime.js';
import { resolveWorkspaceRuntimeRootSync } from '../../../domains/workflow-contract/workspace-runtime.js';
import {
  listActiveNativeHookChanges,
  inspectNativeHookGuard,
  parseNativeHookRequest,
} from '../../../domains/comet-native/native-hook-guard.js';
import {
  createNativeChange,
  listActiveNativeChangesOwnedByWorkspace,
} from '../../../domains/comet-native/native-change.js';
import { createNativePortableChange } from '../../../domains/comet-native/native-portable-requirements.js';
import { createNativeSdkChange } from '../../../domains/comet-native/native-sdk-create.js';
import { isNativeSdkChangeCancellationComplete } from '../../../domains/comet-native/native-sdk-cancellation.js';
import { execFileSync } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';

import { prepareNativeApplication } from '../../helpers/native-application.js';
import { runtimeDispatchCommand } from '../../../app/commands/runtime.js';
import { runNativeCli } from '../../../domains/comet-native/native-cli.js';
import { nativeProjectPaths } from '../../../domains/comet-native/native-paths.js';
import {
  createNativeSdkRuntime,
  inspectNativeSdkRun,
} from '../../../domains/comet-native/native-runtime-ownership.js';
import { settleNativeSdkCancellation } from '../../../domains/comet-native/native-sdk-cancellation-cleanup.js';
import { readCometCurrentSelection } from '../../../domains/workflow-contract/current-selection.js';
import type { RuntimeStoppedAction } from '../../../domains/engine/runtime.js';

const roots: string[] = [];
afterEach(async () => {
  await Promise.all(roots.splice(0).map((root) => fs.rm(root, { recursive: true, force: true })));
});

async function fixture(stage: 'unstarted' | 'approval' | 'builder' = 'unstarted') {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'native-sdk-cancellation-'));
  roots.push(root);
  execFileSync('git', ['init', '-b', 'main'], { cwd: root, stdio: 'ignore' });
  const name = 'cancel-original';
  const cli = async (args: string[]) => {
    const result = await runNativeCli([...args, '--project-root', root, '--json']);
    return JSON.parse(result.stdout!);
  };
  expect((await cli(['new', name])).exitCode).toBe(0);
  const change = path.join(root, 'docs/comet/changes', name);
  const runtime = createNativeSdkRuntime(root);
  if (stage !== 'unstarted') {
    await fs.writeFile(
      path.join(change, 'brief.md'),
      '# Outcome\nKeep partial work.\n# Scope\nCancel safely.\n' +
        '## Directory structure\n### Modified\n- src/ — preserve partial implementation when cancelled.\n# Non-goals\nPublishing.\n' +
        '# Acceptance examples\n- Existing work remains.\n# Constraints and invariants\nPreserve receipts.\n' +
        '# Decisions\nNone.\n# Open questions\nNone.\n# Verification expectations\nRun focused checks.\n',
    );
    await fs.mkdir(path.join(change, 'specs/workflow'), { recursive: true });
    await fs.writeFile(
      path.join(change, 'specs/workflow/spec.md'),
      '# Workflow\nExisting work remains.\n',
    );
    const prepared = await cli(['next', name]);
    expect(prepared.exitCode, prepared.error?.message).toBe(0);
    if (stage === 'builder') {
      const { state } = await inspectNativeSdkRun(root, name);
      const confirmed = await cli([
        'next',
        name,
        '--confirmed',
        '--summary',
        'Confirmed complete Shape',
        '--expected-state-version',
        String(state.state_version),
        '--expected-action',
        'confirm-shape',
      ]);
      expect(confirmed.exitCode, confirmed.error?.message).toBe(0);
    }
  }
  return { root, name, cli, runtime, change };
}

describe('Native cancellation lifecycle', () => {
  it('keeps a cancelled claimed execution active until the original host proves it stopped', async () => {
    const f = await fixture('builder');
    const before = await f.runtime.inspect(f.name);
    const action = before.actions.at(-1)!;
    const claimed = await f.runtime.claim({
      runId: f.name,
      actionId: action.id,
      attempt: action.attempt,
      inputHash: action.inputHash,
      executorId: 'original-host',
      claimToken: 'retained-host-claim',
    });
    await f.runtime.cancel({ runId: f.name, reason: 'Stop scheduling' });
    expect(await isNativeSdkChangeCancellationComplete(f.root, f.name)).toBe(false);
    const store = createFileRuntimeStore({
      rootDir: path.join(resolveWorkspaceRuntimeRootSync(f.root), 'sdk-runs', 'native'),
    });
    expect(await store.readDisposition(f.name)).toBe('active');
    for (const command of [
      `comet native doctor ${f.name} --repair --json`,
      'comet runtime dispatch --application native --request stop-confirmation.json',
    ]) {
      const request = parseNativeHookRequest(
        JSON.stringify({ tool_name: 'Bash', tool_input: { command } }),
      );
      expect(await inspectNativeHookGuard(f.root, request, f.name)).toMatchObject({
        allowed: true,
      });
    }

    expect(
      await inspectNativeHookGuard(f.root, { intent: 'write', targets: ['src/replacement.ts'] }),
    ).toMatchObject({ allowed: false, reason: expect.stringContaining('cancelling') });
    expect(
      await inspectNativeHookGuard(
        f.root,
        { intent: 'write', targets: ['src/replacement.ts'] },
        f.name,
      ),
    ).toMatchObject({ allowed: false, reason: expect.stringContaining('cancelling') });

    expect(await listActiveNativeHookChanges(f.root)).toEqual([
      expect.objectContaining({ name: f.name }),
    ]);
    await f.runtime.cancel({
      runId: f.name,
      reason: 'Original host stopped',
      stoppedActions: [
        {
          actionId: action.id,
          attempt: action.attempt,
          inputHash: action.inputHash,
          claimToken: claimed.actions.at(-1)!.claim!.token,
          evidence: 'The original execution and all of its child tasks stopped.',
        },
      ],
    });
    expect(await isNativeSdkChangeCancellationComplete(f.root, f.name)).toBe(true);
    expect(await store.readDisposition(f.name)).toBe('closed');
    expect(await listActiveNativeHookChanges(f.root)).toEqual([]);
  });

  it('reports pending selection cleanup and the retained root lock age gate instead of declaring cancellation complete', async () => {
    const f = await fixture('unstarted');
    const before = await f.runtime.inspect(f.name);
    const paths = await nativeProjectPaths(
      f.root,
      (before.input as { artifactRootRef: string }).artifactRootRef,
    );
    await fs.mkdir(paths.locksDir, { recursive: true });
    const lock = path.join(paths.locksDir, 'root-move.lock');
    const owner = {
      id: 'controlled-foreign-root',
      pid: 2147483647,
      hostname: 'controlled-foreign-host',
      createdAt: new Date().toISOString(),
      operation: 'Controlled root move interruption',
    };
    await fs.writeFile(lock, JSON.stringify(owner));
    await expect(
      f.runtime.cancel({ runId: f.name, reason: 'Cancel while root cleanup is blocked' }),
    ).rejects.toThrow(/Legacy lock requires confirmation/);
    expect(await f.runtime.inspect(f.name)).toEqual(before);
    // 旧版本可能已经提交取消；保留该故障恢复覆盖，而不是绕过新的提交前保护。
    const application = nativeSdkApplicationForRun(before);
    const legacy = createRuntime({
      store: createFileRuntimeStore({
        rootDir: path.join(resolveWorkspaceRuntimeRootSync(f.root), 'sdk-runs', 'native'),
      }),
      workflows: [application.workflow],
      transitionHandlers: [application.transitionHandler],
      validators: application.validators,
      stateValidators: application.stateValidators,
      commandValidators: application.commandValidators,
    });
    const cancelled = await legacy.cancel({
      runId: f.name,
      reason: 'Legacy committed cancellation',
    });
    await f.runtime.inspect(f.name);
    await expect(
      settleNativeSdkCancellation({ projectRoot: f.root, run: cancelled }),
    ).rejects.toThrow(/current selection release remains pending/);
    const status = await f.cli(['status', f.name]);
    expect(status.data).toMatchObject({
      status: 'cancelling',
      cancellation: {
        quiescent: true,
        cleanupRequired: true,
        cleanup: {
          rootMoveLock: {
            status: 'unknown',
            owner: { id: owner.id, createdAt: owner.createdAt, operation: owner.operation },
            minimumUnknownOwnerAgeMs: 0,
          },
        },
      },
      continuation: {
        disposition: 'blocked',
        commandArgs: ['comet', 'native', 'doctor', '--json', '--project-root', f.root],
      },
    });
    expect(await isNativeSdkChangeCancellationComplete(f.root, f.name)).toBe(false);
    for (const command of [
      `comet native doctor ${f.name} --repair --json`,
      'comet runtime dispatch --application native --request stop-confirmation.json',
    ]) {
      const request = parseNativeHookRequest(
        JSON.stringify({ tool_name: 'Bash', tool_input: { command } }),
      );
      expect(await inspectNativeHookGuard(f.root, request, f.name)).toMatchObject({
        allowed: true,
      });
    }

    expect(
      await inspectNativeHookGuard(f.root, { intent: 'write', targets: ['src/replacement.ts'] }),
    ).toMatchObject({ allowed: false, reason: expect.stringContaining('cancelling') });
    expect(
      await inspectNativeHookGuard(
        f.root,
        { intent: 'write', targets: ['src/replacement.ts'] },
        f.name,
      ),
    ).toMatchObject({ allowed: false, reason: expect.stringContaining('cancelling') });

    expect(await listActiveNativeHookChanges(f.root)).toEqual([
      expect.objectContaining({ name: f.name }),
    ]);
    expect(status.data.cancellation.cleanup.rootMoveLock.remainingMs).toBe(0);
    const doctor = await f.cli(['doctor', f.name]);
    expect(doctor.data.healthy).toBe(false);
    expect(
      doctor.data.findings.some(
        (finding: { code: string }) => finding.code === 'sdk-cancellation-cleanup-pending',
      ),
      JSON.stringify(doctor.data),
    ).toBe(true);
    expect(JSON.parse(await fs.readFile(lock, 'utf8'))).toEqual(owner);
    // 受控假持有者自行释放它创建的锁；不是让 Runtime 绕过未知 owner 的保护。
    await fs.unlink(lock);
    // 锁已由原持有者释放，但选择清理尚未完成，三种创建入口都必须保留阻塞。
    expect(await listActiveNativeChangesOwnedByWorkspace(paths)).toEqual([f.name]);
    const creation = {
      paths,
      name: 'blocked-replacement',
      language: 'en' as const,
      workspaceBinding: { isolation: 'current' as const, changeBranch: null, targetBranch: null },
    };
    for (const create of [createNativeSdkChange, createNativePortableChange, createNativeChange]) {
      await expect(create(creation)).rejects.toThrow(/active|workspace|isolation/i);
    }
    expect(await readCometCurrentSelection(f.root)).toMatchObject({
      status: 'selected',
      selection: { change: f.name },
    });
    expect((await f.cli(['doctor', f.name, '--repair'])).exitCode).toBe(0);
    expect((await f.cli(['status', f.name])).data.status).toBe('cancelled');
    expect((await f.cli(['new', 'after-root-release'])).exitCode).toBe(0);
    await fs.writeFile(lock, JSON.stringify(owner));
    expect((await f.cli(['next', f.name])).exitCode).toBe(0);
    expect((await f.cli(['doctor', f.name, '--repair'])).data.healthy).toBe(true);
    expect((await f.cli(['doctor'])).data.healthy).toBe(false);
    expect(JSON.parse(await fs.readFile(lock, 'utf8'))).toEqual(owner);
    expect(await readCometCurrentSelection(f.root)).toMatchObject({
      status: 'selected',
      selection: { change: 'after-root-release' },
    });
  });

  it.each(['unstarted', 'builder'] as const)(
    'returns actionable cancellation closure directly in the %s CLI response without changing the SDK Run shape',
    async (stage) => {
      const f = await fixture(stage);
      if (stage === 'builder') {
        const run = await f.runtime.inspect(f.name);
        const action = run.actions.find((entry) => entry.stepId === 'build.builder')!;
        await f.runtime.claim({
          runId: f.name,
          actionId: action.id,
          attempt: action.attempt,
          inputHash: action.inputHash,
          executorId: 'original-host',
          claimToken: 'cancellation-response',
        });
      }
      const requestFile = path.join(f.root, 'cancel-request.json');
      await fs.writeFile(
        requestFile,
        JSON.stringify({ operation: 'cancel', runId: f.name, reason: 'Stop this task' }),
      );
      const result = await runtimeDispatchCommand(
        { request: requestFile, application: 'native', projectRoot: f.root },
        { output: 'compact' },
      );
      expect(result.response.status).toBe('succeeded');
      const cli = result.cliResponse as {
        data: unknown;
        cancellation: { status: string };
        continuation: { disposition: string };
      };
      expect(cli.data).toMatchObject(
        result.response.status === 'succeeded' ? result.response.data : null,
      );
      expect(cli.data).toMatchObject({
        continuation: { mode: stage === 'unstarted' ? 'done' : 'reconcile' },
      });
      expect(cli.cancellation.status).toBe(stage === 'unstarted' ? 'cancelled' : 'cancelling');
      expect(cli.continuation.disposition).toBe(stage === 'unstarted' ? 'done' : 'blocked');
    },
  );

  it('releases a cancelled fixed custom Native application from its own store', async () => {
    const root = await fs.mkdtemp(path.join(os.tmpdir(), 'native-custom-cancellation-'));
    roots.push(root);
    const f = await prepareNativeApplication(root);
    const builder = f.pending(f.run, 'build.builder');
    const claimed = await f.claim(builder, 'custom-builder');
    const action = claimed.actions.find(({ id }) => id === builder.id)!;
    await f.dispatch({ operation: 'cancel', runId: f.name, reason: 'Stop this custom task' });
    const cancelling = await f.native(['status', f.name]);
    expect(cancelling).toMatchObject({
      status: 'cancelling',
      application: { id: 'native-candidate-review' },
    });
    await f.dispatch({
      operation: 'cancel',
      runId: f.name,
      reason: 'Original host stopped',
      stoppedActions: [
        {
          actionId: action.id,
          attempt: action.attempt,
          inputHash: action.inputHash,
          claimToken: action.claim!.token,
          evidence: 'Original custom Builder and all its children stopped; candidate.txt retained.',
        },
      ],
    });
    const status = await f.native(['status', f.name]);
    expect(status).toMatchObject({
      status: 'cancelled',
      cancellation: { quiescent: true },
      continuation: { disposition: 'done' },
    });
    expect((await f.native(['new', 'replacement'])).name).toBe('replacement');
    const cancelled = await f.dispatch({ operation: 'inspect', runId: f.name });
    expect(cancelled.status).toBe('cancelled');
    expect(cancelled.actions.find(({ id }) => id === action.id)?.cancellation?.evidence).toContain(
      'retained',
    );
  });
  it.each(['unstarted', 'approval', 'builder'] as const)(
    'ends %s work and releases the workspace without Archive',
    async (stage) => {
      const f = await fixture(stage);
      const before = await f.runtime.inspect(f.name);
      const originalBrief = await fs.readFile(path.join(f.change, 'brief.md'), 'utf8');
      const requestFile = path.join(f.root, 'cancel-request.json');
      await fs.writeFile(
        requestFile,
        JSON.stringify({
          operation: 'cancel',
          runId: f.name,
          expectedRevision: before.revision,
          reason: 'User no longer needs this task',
        }),
      );
      const response = await runtimeDispatchCommand({
        request: requestFile,
        application: 'native',
        projectRoot: f.root,
      });
      expect(response.response.status, JSON.stringify(response.response)).toBe('succeeded');
      const cancelled = await f.runtime.inspect(f.name);
      expect(cancelled.status).toBe('cancelled');
      expect(cancelled.state).toEqual(before.state);
      expect(cancelled.actions.filter(({ status }) => status === 'succeeded')).toEqual(
        before.actions.filter(({ status }) => status === 'succeeded'),
      );
      const status = await f.cli(['status', f.name]);
      expect(status.exitCode, status.error?.message).toBe(0);
      expect(status.data).toMatchObject({
        status: 'cancelled',
        cancellation: { quiescent: true },
        continuation: {
          disposition: 'done',
          status: 'cancelled',
          action: 'none',
          requiredInputs: [],
          commandArgs: null,
        },
      });
      expect(status.data.pendingActions).toBeUndefined();
      expect(status.data.continuation.commandAlternatives).toEqual([]);
      expect(status.data.continuation.requiresUserDecision).toBe(false);
      expect(status.data.continuation.runnerAction.kind).toBe('none');
      const next = await f.cli(['next', f.name, '--summary', 'No further work']);
      expect(next.exitCode).toBe(0);
      expect(next.data.continuation).toEqual(status.data.continuation);
      expect((await f.cli(['doctor', f.name, '--repair'])).data).toMatchObject({
        healthy: true,
        findings: [],
        status: 'cancelled',
      });
      expect(await isNativeSdkChangeCancellationComplete(f.root, f.name)).toBe(true);
      expect(await listActiveNativeHookChanges(f.root)).toEqual([]);
      expect(
        await inspectNativeHookGuard(f.root, { intent: 'write', targets: ['src/replacement.ts'] }),
      ).toMatchObject({ allowed: true });
      expect(await readCometCurrentSelection(f.root)).toEqual({ status: 'missing' });
      expect(await f.runtime.cancel({ runId: f.name, reason: 'Cancel again' })).toEqual(cancelled);
      expect(await fs.readFile(path.join(f.change, 'brief.md'), 'utf8')).toBe(originalBrief);
      const replacement = await f.cli(['new', 'replacement']);
      expect(replacement.exitCode, replacement.error?.message).toBe(0);
      await settleNativeSdkCancellation({ projectRoot: f.root, run: cancelled });
      expect(await readCometCurrentSelection(f.root)).toMatchObject({
        status: 'selected',
        selection: { change: 'replacement' },
      });
      expect((await f.runtime.inspect(f.name)).revision).toBe(cancelled.revision);
    },
  );

  it.each([false, true])(
    'retains a claimed Builder until its original host proves it stopped (unknown=%s)',
    async (unknown) => {
      const f = await fixture('builder');
      const before = await f.runtime.inspect(f.name);
      const builder = before.actions.find(
        ({ stepId, status }) => stepId === 'build.builder' && status === 'pending',
      )!;
      expect(builder).toBeDefined();
      await f.runtime.claim({
        runId: f.name,
        actionId: builder.id,
        attempt: builder.attempt,
        inputHash: builder.inputHash,
        executorId: 'native-host',
        sessionId: 'original-builder',
        claimToken: 'original-claim',
      });
      if (unknown)
        await f.runtime.markUnknown({
          runId: f.name,
          actionId: builder.id,
          attempt: builder.attempt,
          reason: 'Original host temporarily disconnected',
        });
      await fs.writeFile(
        path.join(f.root, 'partial-work.txt'),
        'Preserve my unfinished implementation\n',
      );
      const cancelled = await f.runtime.cancel({
        runId: f.name,
        reason: 'User stopped the original work',
      });
      const status = await f.cli(['status', f.name]);
      expect(status.data).toMatchObject({
        status: 'cancelling',
        continuation: {
          disposition: 'blocked',
          action: 'none',
          requiredInputs: ['original-execution-stop-evidence'],
        },
      });
      expect(status.data.pendingActions).toBeUndefined();
      expect(status.data.continuation.commandAlternatives).toEqual([]);
      expect(status.data.continuation.requiresUserDecision).toBe(false);
      expect(status.data.continuation.runnerAction.kind).toBe('none');
      expect((await f.cli(['new', 'blocked-replacement'])).exitCode).toBe(73);
      expect((await f.cli(['doctor', f.name, '--repair'])).data).toMatchObject({
        healthy: false,
        findings: [{ code: 'sdk-cancellation-execution-unresolved' }],
      });
      const request = status.data.cancellation.outstandingActions[0].acknowledgementRequest;
      expect(request).toMatchObject({
        operation: 'cancel',
        runId: f.name,
        expectedRevision: cancelled.revision,
        stoppedActions: [
          {
            actionId: builder.id,
            attempt: builder.attempt,
            inputHash: builder.inputHash,
            claimToken: 'original-claim',
          },
        ],
      });
      const evidence =
        'Original Builder and all its child tasks are stopped; partial-work.txt is retained.';
      const stopped: RuntimeStoppedAction = { ...request.stoppedActions[0], evidence };
      const requestFile = path.join(f.root, 'stopped-request.json');
      await fs.writeFile(requestFile, JSON.stringify({ ...request, stoppedActions: [stopped] }));
      const response = await runtimeDispatchCommand({
        request: requestFile,
        application: 'native',
        projectRoot: f.root,
      });
      expect(response.response.status, JSON.stringify(response.response)).toBe('succeeded');
      expect((await f.cli(['status', f.name])).data).toMatchObject({
        status: 'cancelled',
        cancellation: { quiescent: true },
      });
      expect((await f.cli(['new', 'replacement'])).exitCode).toBe(0);
      await expect(
        f.runtime.recordOutcome({
          runId: f.name,
          outcome: {
            actionId: builder.id,
            attempt: builder.attempt,
            inputHash: builder.inputHash,
            claimToken: 'original-claim',
            outcomeId: 'late-result',
            status: 'failed',
            output: { summary: 'Late result' },
          },
        }),
      ).rejects.toThrow(/RUN_CANCELLED/);
      expect(await fs.readFile(path.join(f.root, 'partial-work.txt'), 'utf8')).toBe(
        'Preserve my unfinished implementation\n',
      );
      expect(
        (await f.runtime.inspect(f.name)).actions.find(({ id }) => id === builder.id)?.cancellation
          ?.evidence,
      ).toBe(evidence);
    },
  );
});

import { resolveWorkspaceRuntimeRootSync } from '../../../domains/workflow-contract/workspace-runtime.js';
import { fixtureAcceptanceReview } from '../../helpers/native-builder-acceptance-review.js';
import {
  readProjectConfig,
  writeProjectConfig,
} from '../../../domains/comet-native/native-config.js';
import { promises as fs } from 'node:fs';
import { execFileSync, spawn } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';

interface NativeEnvelope {
  command?: string | null;
  exitCode: number;
  data?: {
    phase?: string;
    preparation?: { projectRoot?: string };
    change?: { phase?: string };
    state?: {
      phase?: string;
      state_version?: number;
      loop?: { iteration?: number };
      acceptance?: Array<{ id: string }>;
    };
    findingSummary?: { codes?: string[] };
    continuation?: { disposition?: string };
  };
  error?: { code?: string; message?: string };
}

interface NativeProcessResult extends NativeEnvelope {
  stdout: string;
  stderr: string;
  timedOut: boolean;
}

const NATIVE_SCRIPTS = path.resolve('assets/skills/comet-native/scripts');
const COMMAND_TIMEOUT_MS = 20_000;
const CHANGE_NAMES = ['parallel-alpha', 'parallel-beta'] as const;
const BUSINESS_SOURCE = 'src/business.ts';
const BRIEF = `# Outcome
Keep Native parallel worktrees recoverable.
# Scope
Exercise two independent linked worktrees.
## Directory structure
### Created
None.
### Modified
None.
### Deleted
None.
### Not created
None.
# Non-goals
No model or network access.
# Acceptance examples
- Both worktrees progress without blocking each other.
# Constraints and invariants
Business source edits remain user-authored.
# Decisions
Use process-level Native CLI commands.
# Open questions
None.
# Verification expectations
Run the deterministic parallel-worktree regression test.
`;
const SPEC = `# native parallel worktree probe

## Requirements

### Requirement: Keep independent worktrees usable

Native parallel worktrees MUST progress without crossing Runtime boundaries.

#### Scenario: Two linked worktrees progress

- **WHEN** two changes progress concurrently
- **THEN** each worktree keeps its own state and Runtime
`;

function commandScript(command: string): string {
  return path.join(NATIVE_SCRIPTS, `comet-native-${command}.mjs`);
}

function runNativeCommand(
  command: string,
  args: string[],
  projectRoot: string,
  timeoutMs = COMMAND_TIMEOUT_MS,
  environment: NodeJS.ProcessEnv = process.env,
): Promise<NativeProcessResult> {
  return new Promise((resolve) => {
    const child = spawn(
      process.execPath,
      [commandScript(command), ...args, '--json', '--project-root', projectRoot],
      {
        cwd: projectRoot,
        env: environment,
        stdio: ['ignore', 'pipe', 'pipe'],
        windowsHide: true,
      },
    );
    let stdout = '';
    let stderr = '';
    let timedOut = false;
    let settled = false;
    const timer = setTimeout(() => {
      timedOut = true;
      child.kill();
    }, timeoutMs);

    child.stdout.on('data', (chunk: Buffer | string) => {
      stdout += chunk.toString();
    });
    child.stderr.on('data', (chunk: Buffer | string) => {
      stderr += chunk.toString();
    });
    child.once('error', (error) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve({
        exitCode: -1,
        stdout,
        stderr: `${stderr}${error.message}`,
        timedOut,
      });
    });
    child.once('close', (code) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      let envelope: NativeEnvelope;
      try {
        envelope = JSON.parse(stdout) as NativeEnvelope;
      } catch {
        envelope = { exitCode: code ?? -1 };
      }
      resolve({
        ...envelope,
        exitCode: envelope.exitCode ?? code ?? -1,
        stdout,
        stderr,
        timedOut,
      });
    });
  });
}

function assertCompleted(result: NativeProcessResult, label: string): void {
  expect(result.timedOut, `${label} timed out\n${result.stderr}`).toBe(false);
  expect(result.exitCode, `${label}\n${result.stdout}\n${result.stderr}`).toBe(0);
}

async function submitBuilderHandoff(
  name: string,
  projectRoot: string,
  reviewerExecutionRef = `reviewer-${name}`,
): Promise<NativeProcessResult> {
  const shown = await runNativeCommand('show', [name], projectRoot);
  assertCompleted(shown, `show ${name}`);
  const ids = shown.data?.state?.acceptance?.map(({ id }) => id);
  expect(ids).toBeDefined();
  const input = path.join(projectRoot, `.runner-input-${name}.json`);
  await fs.writeFile(
    input,
    JSON.stringify({
      kind: 'builder-handoff',
      summary: 'Implemented the confirmed behavior.',
      addressed_acceptance_ids: ['A1'],
      acceptance_review: fixtureAcceptanceReview(ids!),
      checks: [],
      known_limits: [],
      review: {
        status: 'passed',
        summary: 'Read-only review passed.',
        reviewer_execution_ref: reviewerExecutionRef,
      },
    }),
  );
  try {
    return await runNativeCommand('next', [name, '--runner-input', input], projectRoot);
  } finally {
    await fs.rm(input, { force: true });
  }
}

async function readDirectoryOrEmpty(directory: string): Promise<string[]> {
  try {
    return (await fs.readdir(directory)).sort();
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return [];
    throw error;
  }
}

describe('Native parallel linked-worktree Runtime', () => {
  const repositories: string[] = [];
  const linkedWorktrees: Array<{ repository: string; root: string }> = [];

  afterEach(async () => {
    for (const { repository, root } of linkedWorktrees.splice(0)) {
      try {
        execFileSync('git', ['worktree', 'remove', '--force', root], {
          cwd: repository,
          stdio: 'ignore',
        });
      } catch {
        // The assertion failure is more useful than cleanup noise.
      }
      await fs.rm(root, { recursive: true, force: true });
    }
    await Promise.all(
      repositories
        .splice(0)
        .map((repository) => fs.rm(repository, { recursive: true, force: true })),
    );
  });

  async function exerciseParallelEdits(documentWrites: 'allow' | 'revert') {
    const repository = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-native-parallel-'));
    repositories.push(repository);
    execFileSync('git', ['init'], { cwd: repository, stdio: 'ignore' });
    execFileSync('git', ['config', 'user.email', 'native@example.test'], {
      cwd: repository,
      stdio: 'ignore',
    });
    execFileSync('git', ['config', 'user.name', 'Native Test'], {
      cwd: repository,
      stdio: 'ignore',
    });

    const initialized = await runNativeCommand(
      'init',
      ['--root', 'docs', '--language', 'en'],
      repository,
    );
    assertCompleted(initialized, 'initialize Native fixture');
    if (documentWrites === 'revert') {
      const config = (await readProjectConfig(repository))!;
      await writeProjectConfig(repository, {
        ...config,
        native: { ...config.native, document_writes: 'revert' },
      });
    }
    await fs.mkdir(path.join(repository, 'src'), { recursive: true });
    await fs.writeFile(path.join(repository, BUSINESS_SOURCE), 'export const value = "base";\n');
    execFileSync('git', ['add', '.comet/config.yaml', BUSINESS_SOURCE], {
      cwd: repository,
      stdio: 'ignore',
    });
    execFileSync('git', ['commit', '-m', 'seed Native parallel fixture'], {
      cwd: repository,
      stdio: 'ignore',
    });
    const targetBranch = execFileSync('git', ['branch', '--show-current'], {
      cwd: repository,
      encoding: 'utf8',
    }).trim();

    const created = await Promise.all(
      CHANGE_NAMES.map((name) =>
        runNativeCommand(
          'new',
          [name, '--isolation', 'worktree', '--target-branch', targetBranch, '--runtime', 'compat'],
          repository,
        ),
      ),
    );
    created.forEach((result, index) => assertCompleted(result, `create ${CHANGE_NAMES[index]}`));

    const worktrees = await Promise.all(
      CHANGE_NAMES.map(async (name) => ({
        name,
        root: await fs.realpath(path.resolve(repository, '.worktrees', name)),
      })),
    );
    worktrees.forEach(({ root }) => linkedWorktrees.push({ repository, root }));
    expect(new Set(created.map((result) => result.data?.preparation?.projectRoot))).toEqual(
      new Set(worktrees.map(({ root }) => root)),
    );
    const worktreeList = execFileSync('git', ['worktree', 'list', '--porcelain'], {
      cwd: repository,
      encoding: 'utf8',
    }).replaceAll('\\', '/');
    expect(worktreeList).toContain(worktrees[0].root.replaceAll('\\', '/'));
    expect(worktreeList).toContain(worktrees[1].root.replaceAll('\\', '/'));

    await Promise.all(
      worktrees.map(async ({ name, root }) => {
        const changeDir = path.join(root, 'docs', 'comet', 'changes', name);
        await fs.writeFile(path.join(changeDir, 'brief.md'), BRIEF);
        await fs.mkdir(path.join(changeDir, 'specs', 'parallel-probe'), { recursive: true });
        await fs.writeFile(path.join(changeDir, 'specs', 'parallel-probe', 'spec.md'), SPEC);

        const prepared = await runNativeCommand(
          'next',
          [name, '--summary', 'Prepare the parallel worktree contract confirmation'],
          root,
        );
        assertCompleted(prepared, `prepare shape ${name}`);
        expect(prepared.data?.state).toMatchObject({ phase: 'shape', status: 'await-user' });
        const shaped = await runNativeCommand(
          'next',
          [
            name,
            '--summary',
            'Confirm the parallel worktree contract',
            '--confirmed',
            '--expected-state-version',
            String(prepared.data?.state?.state_version),
            '--expected-action',
            'confirm-shape',
          ],
          root,
        );
        assertCompleted(shaped, `shape ${name}`);
        expect(shaped.data?.state?.phase).toBe('build');

        await fs.writeFile(
          path.join(root, BUSINESS_SOURCE),
          `export const value = "${name}-implementation";\n`,
        );
        const built = await submitBuilderHandoff(name, root);
        assertCompleted(built, `build ${name}`);
        expect(built.data?.state?.phase).toBe('verify');
      }),
    );

    const editedWorktree = worktrees[0];
    const untouchedWorktree = worktrees[1];
    const userSource = 'export const value = "user-edited-during-verify";\n';
    const guard = await runNativeCommand(
      'hook-guard',
      [],
      editedWorktree.root,
      COMMAND_TIMEOUT_MS,
      { ...process.env, FILE_PATH: BUSINESS_SOURCE },
    );
    if (documentWrites === 'revert') {
      expect(guard.exitCode, guard.stderr).toBe(2);
      expect(guard.data).toMatchObject({ allowed: false, phase: 'verify' });
    } else {
      expect(guard.exitCode, guard.stderr).toBe(0);
      expect(guard.data).toMatchObject({ allowed: true, phase: 'verify' });
    }
    await fs.writeFile(path.join(editedWorktree.root, BUSINESS_SOURCE), userSource);

    assertCompleted(
      await runNativeCommand(
        'next',
        [
          editedWorktree.name,
          '--revise-implementation',
          '--summary',
          'Confirmed business value revision',
        ],
        editedWorktree.root,
      ),
      'revise the edited implementation',
    );

    const [editedStatus, untouchedStatus] = await Promise.all([
      runNativeCommand('status', [editedWorktree.name], editedWorktree.root),
      runNativeCommand('status', [untouchedWorktree.name], untouchedWorktree.root),
    ]);
    assertCompleted(editedStatus, 'status after manual source edit');
    assertCompleted(untouchedStatus, 'status in untouched worktree');
    expect(editedStatus.data?.phase).toBe('build');
    expect(editedStatus.data?.continuation?.disposition).not.toBe('blocked');
    expect(untouchedStatus.data?.phase).toBe('verify');
    await expect(
      fs.readFile(path.join(untouchedWorktree.root, BUSINESS_SOURCE), 'utf8'),
    ).resolves.toBe('export const value = "parallel-beta-implementation";\n');

    const rebuilt = await submitBuilderHandoff(
      editedWorktree.name,
      editedWorktree.root,
      `reviewer-${editedWorktree.name}-repair`,
    );
    assertCompleted(rebuilt, 'rebuild edited worktree');
    expect(rebuilt.data?.state?.phase).toBe('verify');
    await expect(
      fs.readFile(path.join(editedWorktree.root, BUSINESS_SOURCE), 'utf8'),
    ).resolves.toBe(userSource);

    for (const { root } of worktrees) {
      const locks = path.join(resolveWorkspaceRuntimeRootSync(root), 'native', 'locks');
      const lockEntries = await readDirectoryOrEmpty(locks);
      expect(
        lockEntries.filter(
          (entry) =>
            entry !== '.coordinator' && !/\.lock\.sqlite(?:-journal|-wal|-shm)?$/u.test(entry),
        ),
      ).toEqual([]);
      expect(
        (await readDirectoryOrEmpty(path.join(locks, '.coordinator'))).filter(
          (entry) => entry !== '.protocol-v2.claim',
        ),
      ).toEqual([]);
      expect(
        await readDirectoryOrEmpty(
          path.join(resolveWorkspaceRuntimeRootSync(root), 'native', 'transactions'),
        ),
      ).toEqual([]);
      expect(
        execFileSync('git', ['branch', '--show-current'], { cwd: root, encoding: 'utf8' }).trim(),
      ).toBe(`comet/${path.basename(root)}`);
      const selection = JSON.parse(
        await fs.readFile(path.join(root, '.comet', 'current-change.json'), 'utf8'),
      ) as { workflow: string; change: string };
      expect(selection).toMatchObject({ workflow: 'native', change: path.basename(root) });
    }
    await expect(
      fs.access(path.join(repository, 'docs', 'comet', 'changes', 'parallel-alpha')),
    ).rejects.toMatchObject({ code: 'ENOENT' });
    await expect(
      fs.access(path.join(repository, 'docs', 'comet', 'changes', 'parallel-beta')),
    ).rejects.toMatchObject({ code: 'ENOENT' });
  }

  it('keeps concurrent linked worktrees usable after a manual business-source edit', async () => {
    await exerciseParallelEdits('revert');
  }, 120_000);

  it('rejects the retired checkpoint bundle on a linked-worktree-capable host', async () => {
    const repository = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-native-retired-command-'));
    repositories.push(repository);
    execFileSync('git', ['init'], { cwd: repository, stdio: 'ignore' });
    const result = await runNativeCommand('runtime', ['checkpoint', 'legacy-change'], repository);
    expect(result.timedOut).toBe(false);
    expect(result.exitCode).toBe(64);
    expect(result.error?.code).toBe('usage');
  }, 30_000);
});

