          loop: { iteration: 1, attempt: 1, retry_epoch: 0 },
          blockers: [{ resolution_action: 'resolve-verifier-blocker' }],
        },
        continuation: {
          action: 'resolve-verifier-blocker',
          commandArgs: null,
          commandAlternatives: expect.arrayContaining([
            expect.objectContaining({
              name: 'resolve-verifier-blocker',
              requiredInputs: ['summary', 'user-resolution'],
            }),
            expect.objectContaining({ name: 'revise-implementation' }),
            expect.objectContaining({ name: 'revise-requirements' }),
          ]),
        },
      },
    });
    const paths = await nativeProjectPaths(projectRoot, 'docs'),
      state = await readNativePortableChange(paths, name),
      before = await fs.readFile(nativePortableStateFile(paths, name), 'utf8'),
      summary =
        'SIMULATED USER clarified the selected public behavior; keep the existing candidate.';
    const stale = json(
      await runNativeCli([
        'next',
        name,
        '--resolve-verifier-blocker',
        '--summary',
        summary,
        '--expected-state-version',
        String(state.state_version - 1),
        '--expected-action',
        'resolve-verifier-blocker',
        '--json',
        ...projectArgs(),
      ]),
    );
    expect(stale.exitCode).not.toBe(0);
    expect(await fs.readFile(nativePortableStateFile(paths, name), 'utf8')).toBe(before);
    const resolved = json(
      await runNativeCli([
        'next',
        name,
        '--resolve-verifier-blocker',
        '--summary',
        summary,
        '--expected-state-version',
        String(state.state_version),
        '--expected-action',
        'resolve-verifier-blocker',
        '--json',
        ...projectArgs(),
      ]),
    );
    expect(resolved).toMatchObject({
      exitCode: 0,
      data: {
        state: {
          phase: 'verify',
          status: 'active',
          verification_result: 'pending',
          loop: { iteration: 1, attempt: 1, retry_epoch: 1 },
        },
        continuation: { action: 'dispatch-verifier' },
      },
    });
    const resumed = await readNativePortableChange(paths, name);
    expect(resumed.builder_handoff).toEqual(state.builder_handoff);
    expect(resumed.history.at(-1)!.summary.text).toBe(summary);
    const dispatch = await runnerStep(name, {
      kind: 'dispatch-verifier',
      checks: [],
    });
    expect(dispatch).toMatchObject({
      exitCode: 0,
      data: {
        verifierDispatch: {
          candidateId: state.builder_handoff!.candidate_id,
          iteration: 1,
          attempt: 2,
          recoveryContext: { text: summary, truncated: false },
        },
      },
    });
    expect((dispatch.data!.verifierDispatch as any).acceptance.map((a: any) => a.id)).toEqual(ids);
    const pass = await runnerStep(name, finalResponse(1, 2, ids));
    expect(pass).toMatchObject({
      exitCode: 0,
      data: {
        state: {
          phase: 'verify',
          status: 'await-user',
          verification_result: 'pass',
          loop: { attempt: 2 },
        },
      },
    });
  });
});

