    worktree.inspectGitWorktree.mockReturnValueOnce({
      isGitWorktree: true,
      currentBranch: null,
      primaryWorktreeRoot: projectRoot,
      currentWorktreeRoot: projectRoot,
      isSecondaryWorktree: false,
    });
    await expect(
      prepareNativeWorkspace({
        projectRoot,
        name: 'detached',
