  it('prepares a new branch, resumes an existing branch, and wraps config failure', async () => {
    worktree.isLocalGitBranch.mockReturnValueOnce(true).mockReturnValueOnce(false);
    await expect(
      prepareNativeWorkspace({
        projectRoot,
        name: 'new-branch',
